/**
 * Automatically generates clean, standardized system codes from entity names.
 * Adheres strictly to: All system codes must be generated by the system from the inputted name.
 * Never requests the user to manually invent or input internal system identifiers.
 */

/**
 * Generates an uppercase organization system code from its commercial name.
 * Format: Alphanumeric uppercase with underscores, max 30 chars.
 * Example: "Acme Global Solutions" -> "ACME_GLOBAL_SOLUTIONS"
 */
export function generateOrganizationCode(name: string): string {
  const clean = name
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
  if (!clean) return '';
  const result = clean.slice(0, 30);
  return result.length < 2 ? `${result}_ORG`.slice(0, 30) : result;
}

/**
 * Generates a lowercase navigation menu system code from its title.
 * Format: Alphanumeric lowercase with underscores, max 50 chars.
 * Example: "User Management & RBAC" -> "user_management_rbac"
 */
export function generateMenuCode(title: string): string {
  const clean = title
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
  return clean.slice(0, 50);
}

/**
 * Generates a lowercase role system code from its human-readable name.
 * Format: Alphanumeric lowercase with underscores, starting with letter, max 50 chars.
 * Example: "Finance Officer" -> "finance_officer"
 */
export function generateRoleCode(name: string): string {
  let clean = name
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
  if (!clean) return '';
  if (!/^[a-z]/.test(clean)) {
    clean = `role_${clean}`;
  }
  return clean.slice(0, 50);
}

/**
 * Generates a standard permission system code from resource and action.
 * Format: resource.action
 * Example: resource "invoices", action "approve" -> "invoices.approve"
 */
export function generatePermissionCode(resource: string, action: string): string {
  const cleanResource = resource.trim().toLowerCase().replace(/[^a-z0-9_]+/g, '');
  const cleanAction = action.trim().toLowerCase().replace(/[^a-z0-9_]+/g, '');
  if (!cleanResource && !cleanAction) return '';
  if (!cleanResource) return cleanAction;
  if (!cleanAction) return cleanResource;
  return `${cleanResource}.${cleanAction}`;
}

/**
 * Generates an uppercase system code from a master catalog entity name or label.
 * Format: Alphanumeric uppercase with underscores.
 * Example: "Software & Technology" -> "SOFTWARE_TECHNOLOGY"
 * Example: "VAT 18%" -> "VAT_18"
 * Example: "Kilogram" -> "KILOGRAM"
 */
export function generateMasterCode(nameOrLabel: string, maxLength: number = 30): string {
  const clean = nameOrLabel
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
  if (!clean) return '';
  return clean.slice(0, maxLength);
}
